from de import *
T=[]
def konjunktiv():
    t=DT('kl8-deu-konjunktiv','kl8','Verbformen','Konjunktiv I und II',seed=181)
    t.th('basis','Konjunktiv','Konjunktiv I braucht man für die indirekte Rede: Er sagt, er sei krank. Konjunktiv II drückt Möglichkeit oder Wunsch aus: Ich hätte Zeit.')
    THEORY(t,"Du erzählst, was dir ein Freund gesagt hat: «Er sagt, er sei krank.» Oder du träumst: «Wenn ich Zeit hätte, käme ich mit.» Beides sind Möglichkeitsformen.",SC('talk',t1='Ich bin krank.',t2='Er sagt, er sei krank.'),
      "Drei Formen: wirklich, weitergegeben und möglich.",["Form","Wofür?","Beispiel"],[["{7|Indikativ}","Wirklichkeit","Er ist krank."],["{0|Konjunktiv I}","Indirekte Rede","Er sagt, er {0|sei} krank."],["{1|Konjunktiv II}","Möglichkeit, Wunsch","Wenn ich Zeit {1|hätte}, käme ich."]],
      "Die Farben zeigen die Form.",
      [([("Anna sagt:","",7),("«Ich bin müde.»","Indikativ",7)],"Direkte Rede."),([("Anna sagt,","",7),("sie sei","Konjunktiv I",0),("müde.","",7)],"Indirekte Rede mit Konjunktiv I."),([("Wenn","",7),("ich","",7),("Zeit hätte,","Konjunktiv II",1),("käme ich.","Konjunktiv II",1)],"Möglichkeit mit Konjunktiv II.")],
      "So bildest du die Formen.",["Entscheide: Gibst du wieder, was jemand gesagt hat? Dann Konjunktiv I.","Bilde Konjunktiv I vom Stamm: er gehe, sie habe, er sei.","Drückst du eine Möglichkeit oder einen Wunsch aus? Dann Konjunktiv II.","Bilde Konjunktiv II: ich wäre, ich hätte, ich käme oder würde + Grundform.","Prüfe, ob die Form vom Indikativ abweicht."],
      "Das ist wichtig.",[["Indirekte Rede","Konjunktiv I: er sei, sie habe, er gehe.","Er sagt, er sei krank.",0],["Möglichkeit","Konjunktiv II: wäre, hätte, käme, würde gehen.","Ich würde gern fliegen.",1],["Ersatz","Ist Konjunktiv I gleich wie Indikativ, nimm Konjunktiv II.","Sie sagten, sie hätten Zeit.",3]],
      fehler=[["Er sagt, er ist krank.","Er sagt, er sei krank.","Indirekte Rede: Konjunktiv I."],["Wenn ich Zeit habe, käme ich.","Wenn ich Zeit hätte, käme ich.","Möglichkeit: Konjunktiv II."],["Sie sagte, sie hatte keine Zeit.","Sie sagte, sie habe keine Zeit.","Konjunktiv I: habe."]])
    C=['Indikativ','Konjunktiv I','Konjunktiv II']
    S=[("Er ist krank.",0),("Er sagt, er sei krank.",1),("Wenn ich Zeit hätte, käme ich mit.",2),("Sie hat keine Zeit.",0),("Sie sagte, sie habe keine Zeit.",1),("Ich würde gern fliegen.",2),("Wir gehen ins Kino.",0),("Der Lehrer meinte, die Aufgabe sei leicht.",1),("Er könnte uns helfen.",2),("Anna erzählt, sie gehe oft schwimmen.",1),("Wenn es nicht regnen würde, gingen wir hinaus.",2),("Tom behauptet, er kenne den Weg.",1),("Sie wüsste die Antwort.",2),("Die Zeitung schreibt, der Minister komme morgen.",1),("Der Zug fährt um acht.",0),("Wäre es doch Sommer!",2),("Mein Bruder sagt, er habe Hunger.",1),("Ich hätte gern ein Eis.",2),("Es regnet seit Stunden.",0),("Die Ärztin sagte, der Patient sei gesund.",1)]
    cls(t,S,C,lambda p:"%s\nIn welcher Form steht das Verb?"%p,hint=["Es ist wirklich so.","Jemand sagt etwas weiter: sei, habe, gehe.","Es ist nur möglich oder gewünscht: wäre, hätte, würde."],why=lambda p,c:["Es ist eine Tatsache: Indikativ.","Weitergegebene Aussage: Konjunktiv I.","Möglichkeit oder Wunsch: Konjunktiv II."][c],ne=6,disp=lambda p:p,mq='Tippe alle Sätze im {s} an.',mt=2,sel=True,sq='Welcher Satz steht im {c}?',sqx='Welcher dieser Sätze steht im {c}?',jnt='Stimmt das? Das Verb steht im {c}.',jnp=True,ntyp=4,ntx=0)
    gaps(t,[("Anna sagt, sie ___ müde.","sei",["ist","war","sein"]),("Tom sagt, er ___ Hunger.","habe",["hat","hatte","haben"]),("Wenn ich Zeit ___, käme ich mit.","hätte",["habe","hatte","hat"]),("Lena erzählt, sie ___ gern schwimmen.","gehe",["geht","ging","gehen"]),("Ich ___ gern fliegen können.","würde",["werde","wurde","wird"]),("Der Lehrer sagt, die Aufgabe ___ leicht. (Konjunktiv I)","sei",["ist","war","sein"]),("Wenn ich reich ___, kaufte ich ein Haus.","wäre",["bin","war","sei"])],ne=4,q='Welche Verbform passt? Achte auf Konjunktiv I oder II.')
    forms(t,[("Indirekte Rede: Anna sagt: «Ich bin müde.»",["Anna sagt, sie sei müde.","Anna sagt, dass sie müde sei."]),("Indirekte Rede: Tom sagt: «Ich habe Hunger.»",["Tom sagt, er habe Hunger.","Tom sagt, dass er Hunger habe."]),("Indirekte Rede: Lena sagt: «Ich gehe nach Hause.»",["Lena sagt, sie gehe nach Hause.","Lena sagt, dass sie nach Hause gehe."]),("Indirekte Rede: Max sagt: «Ich kann schwimmen.»",["Max sagt, er könne schwimmen.","Max sagt, dass er schwimmen könne."]),("Konjunktiv II: Ich habe Zeit.",["Ich hätte Zeit."]),("Konjunktiv II: Ich bin reich.","Ich wäre reich."),("Konjunktiv II: Er geht.",["Er ginge.","Er würde gehen."]),("Konjunktiv II: Wir kommen.",["Wir kämen.","Wir würden kommen."])],ne=4,hint='Schreibe den ganzen Satz.')
    fixes(t,[("Er sagt, er ist krank.","Er sagt, er sei krank."),("Sie sagte, sie hatte keine Zeit.","Sie sagte, sie habe keine Zeit."),("Wenn ich Zeit habe, käme ich.","Wenn ich Zeit hätte, käme ich."),("Er meinte, er kann nicht kommen.","Er meinte, er könne nicht kommen."),("Wenn ich reich bin, kaufte ich ein Schloss.","Wenn ich reich wäre, kaufte ich ein Schloss.")],ne=2,q='Setze die richtige Verbform ein.')
    return t
T.append(konjunktiv)

def hauptneben(ch,hard):
    t=DT('%s-deu-hauptneben'%ch,ch,'Satzanalyse','Hauptsätze und Nebensätze',seed=191+int(ch[2:]))
    t.th('basis','Haupt- und Nebensatz','Ein Hauptsatz kann allein stehen. Ein Nebensatz wird mit einem Einleitewort (weil, dass, obwohl, wenn …) eingeleitet. Sein Verb steht am Ende.')
    THEORY(t,"«Wir bleiben zu Hause.» Das ist ein ganzer Satz. «weil es regnet» ist es nicht: Der Teil braucht den Hauptsatz.",SC('words',words=[['Wir bleiben zu Hause,','#34A853'],['weil','#D93F8E'],['es regnet','#4285F4']],say='Haupt- und Nebensatz'),
      "Zwei Arten von Sätzen.",["Satzart","Merkmale","Beispiel"],[["{2|Hauptsatz}","Verb an 2. Stelle, kann allein stehen","{2|Wir bleiben zu Hause.}"],["{0|Nebensatz}","Einleitewort, Verb am Ende, braucht Hauptsatz","{0|weil es regnet}"]],
      "So sieht ein Satzgefüge aus.",
      [([("Wir bleiben zu Hause","Hauptsatz",2),(",","",7),("weil","Einleitewort",6),("es regnet","Nebensatz",0)],"Wir bleiben zu Hause, weil es regnet."),([("Ich weiss","Hauptsatz",2),(",","",7),("dass","Einleitewort",6),("du kommst","Nebensatz",0)],"Ich weiss, dass du kommst."),([("Obwohl","Einleitewort",6),("sie müde ist","Nebensatz",0),(",","",7),("lernt sie","Hauptsatz",2)],"Der Nebensatz kann auch vorne stehen.")],
      "So erkennst du den Nebensatz.",["Suche das Verb im Satzteil.","Steht es am Ende? Dann ist es oft ein Nebensatz.","Gibt es ein Einleitewort (weil, dass, obwohl, wenn, damit)?","Kann der Teil allein stehen? Wenn nicht, ist er ein Nebensatz."],
      "Das ist wichtig.",[["Hauptsatz","Verb an zweiter Stelle.","Ich lerne.",2],["Nebensatz","Verb am Ende.","weil ich lerne",0],["Komma","Zwischen Haupt- und Nebensatz steht ein Komma.","…, weil …",1]],
      fehler=[["weil es ist kalt","weil es kalt ist","Im Nebensatz steht das Verb am Ende."],["dass er kommt morgen","dass er morgen kommt","Verb ans Ende."],["Wir bleiben zu Hause weil es regnet.","Wir bleiben zu Hause, weil es regnet.","Komma zwischen den Sätzen."]])
    if not hard:
        S=[("Wir bleiben zu Hause.",0),("weil es regnet",1),("Die Sonne scheint.",0),("obwohl sie müde ist",1),("Der Bus kommt pünktlich.",0),("dass du kommst",1),("Er lacht laut.",0),("wenn es dunkel wird",1),("Sie liest ein Buch.",0),("nachdem wir gegessen haben",1),("Der Hund bellt.",0),("damit wir pünktlich sind",1),("Ich mache meine Hausaufgaben.",0),("als ich klein war",1),("Meine Schwester spielt Klavier.",0),("weil sie es liebt",1)]
        FX=[("weil es ist kalt","weil es kalt ist"),("dass er kommt morgen","dass er morgen kommt"),("obwohl sie hat Hunger","obwohl sie Hunger hat"),("wenn es regnet stark","wenn es stark regnet"),("weil ich bin müde","weil ich müde bin"),("damit wir sind pünktlich","damit wir pünktlich sind"),("nachdem er hat gegessen","nachdem er gegessen hat"),("als ich war klein","als ich klein war")]
        VB=[("Verbinde mit «weil»: Ich bleibe zu Hause. Es regnet.",["Ich bleibe zu Hause, weil es regnet.","Weil es regnet, bleibe ich zu Hause."]),("Verbinde mit «dass»: Ich weiss. Du kommst.",["Ich weiss, dass du kommst."]),("Verbinde mit «obwohl»: Sie lernt. Sie ist müde.",["Sie lernt, obwohl sie müde ist.","Obwohl sie müde ist, lernt sie."]),("Verbinde mit «wenn»: Ich rufe dich an. Ich habe Zeit.",["Ich rufe dich an, wenn ich Zeit habe.","Wenn ich Zeit habe, rufe ich dich an."]),("Verbinde mit «damit»: Ich lerne. Ich bestehe die Prüfung.",["Ich lerne, damit ich die Prüfung bestehe.","Damit ich die Prüfung bestehe, lerne ich."]),("Verbinde mit «weil»: Er ist glücklich. Er hat gewonnen.",["Er ist glücklich, weil er gewonnen hat.","Weil er gewonnen hat, ist er glücklich."])]
    else:
        S=[("Ich glaube",0),("dass er kommt",1),("weil er es versprochen hat",1),("Sie wusste nicht",0),("ob der Zug pünktlich abfährt",1),("Obwohl es seit Stunden regnet",1),("gehen die Kinder hinaus",0),("Die Lehrerin erklärt",0),("wie man den Aufsatz plant",1),("Wir fahren in die Berge",0),("sobald die Ferien beginnen",1),("Ich hoffe",0),("dass du bald wieder gesund bist",1),("Bevor der Film beginnt",1),("kaufen wir Popcorn",0),("Mein Bruder backt einen Kuchen",0),("der gern kocht",1),("Der Chef sagt",0),("dass die Sitzung später beginnt",1)]
        FX=[("weil er hat es versprochen","weil er es versprochen hat"),("dass er kommt heute","dass er heute kommt"),("ob der Zug fährt pünktlich ab","ob der Zug pünktlich abfährt"),("sobald die Ferien fangen an","sobald die Ferien anfangen"),("obwohl es regnet seit Stunden","obwohl es seit Stunden regnet"),("bevor wir sind gegangen","bevor wir gegangen sind"),("dass sie wird kommen","dass sie kommen wird"),("nachdem er hat angerufen","nachdem er angerufen hat")]
        VB=[("Verbinde mit «obwohl»: Wir gehen hinaus. Es regnet stark.",["Wir gehen hinaus, obwohl es stark regnet.","Obwohl es stark regnet, gehen wir hinaus."]),("Verbinde mit «dass»: Ich hoffe. Du bist bald gesund.",["Ich hoffe, dass du bald gesund bist."]),("Verbinde mit «bevor»: Wir kaufen Popcorn. Der Film beginnt.",["Wir kaufen Popcorn, bevor der Film beginnt.","Bevor der Film beginnt, kaufen wir Popcorn."]),("Verbinde mit «weil»: Er bleibt zu Hause. Er ist krank.",["Er bleibt zu Hause, weil er krank ist.","Weil er krank ist, bleibt er zu Hause."]),("Verbinde mit «sobald»: Wir fahren los. Die Ferien beginnen.",["Wir fahren los, sobald die Ferien beginnen.","Sobald die Ferien beginnen, fahren wir los."]),("Verbinde mit «ob»: Ich frage. Der Zug fährt pünktlich.",["Ich frage, ob der Zug pünktlich fährt."])]
    if hard:more(t,'Mehrere Nebensätze','Ein Satz kann mehrere Nebensätze haben. Auch ein Nebensatz kann einen weiteren Nebensatz haben. Jeder Nebensatz hat sein Verb am Ende.',TBL(['Satz','Hauptsatz','Nebensätze'],[['Ich glaube, dass er kommt, weil er es versprochen hat.','Ich glaube','dass er kommt; weil er es versprochen hat'],['Sie wusste nicht, ob der Zug pünktlich abfährt.','Sie wusste nicht','ob der Zug pünktlich abfährt']]))
    cls(t,S,['Hauptsatz','Nebensatz'],lambda p:"Ist das ein Hauptsatz oder ein Nebensatz?\n«%s»"%p if False else "«%s»\nHauptsatz oder Nebensatz?"%p,hint=["Es kann allein stehen, das Verb steht an 2. Stelle.","Es hat ein Einleitewort, das Verb steht am Ende."],why=lambda p,c:"Es kann allein stehen: Hauptsatz." if c==0 else "Einleitewort und Verb am Ende: Nebensatz.",disp=lambda p:p,ne=6,mq='Tippe alle {c} an.',mt=3,sel=True,ns=6,nsx=0,ntyp=6,ntx=2)
    fixes(t,FX,ne=4,q='Stelle den Nebensatz richtig.',hint='Im Nebensatz steht das Verb am Ende.')
    forms(t,VB,ne=3,hint='Schreibe den ganzen Satz mit Komma.')
    gaps(t,[("Wir bleiben zu Hause, ___ es regnet.","weil",["aber","denn","und"]) if False else ("Ich weiss, ___ du kommst.","dass",["denn","aber","und"]),("Sie lernt, ___ sie müde ist.","obwohl",["denn","aber","dass"]),("Ich bleibe daheim, ___ ich krank bin.","weil",["aber","dass","oder"]),("Er geht hinaus, ___ es dunkel wird.","bevor",["denn","aber","oder"])],ne=3,q='Welches Einleitewort passt?')
    return t
T+= [lambda:hauptneben('kl8',False),lambda:hauptneben('kl9',True)]

def nebenarten(ch,hard):
    t=DT('%s-deu-nebensatzarten'%ch,ch,'Satzanalyse','Nebensatzarten',seed=201+int(ch[2:]))
    t.th('basis','Nebensatzarten','Relativsätze beschreiben ein Nomen (der, die, das). Konjunktionalsätze beginnen mit weil, obwohl, wenn, dass, damit, als, nachdem.')
    THEORY(t,"«Das Buch, das ich lese, ist spannend.» und «Ich lese, weil es spannend ist.» Beide haben Nebensätze, aber sie arbeiten anders.",SC('words',words=[['Das Buch,','#4285F4'],['das ich lese,','#00A5BF'],['ist spannend','#34A853']],say='Der Nebensatz beschreibt das Nomen'),
      "Zwei wichtige Arten von Nebensätzen.",["Art","Einleitewort","Aufgabe","Beispiel"],[["{5|Relativsatz}","der, die, das, welcher","beschreibt ein Nomen","Das Buch, {5|das ich lese}, ist neu."],["{6|Konjunktionalsatz}","weil, obwohl, wenn, dass, damit","gibt Grund, Zeit, Bedingung …","Ich lese, {6|weil es spannend ist}."]],
      "So wirken die Nebensätze.",
      [([("Das Buch","Nomen",0),(",","",7),("das ich lese","Relativsatz",5),(",","",7),("ist neu","Hauptsatz",2)],"Der Relativsatz erklärt «Buch»."),([("Wir bleiben zu Hause","Hauptsatz",2),(",","",7),("weil es regnet","Konjunktionalsatz",6)],"Der Konjunktionalsatz nennt den Grund."),([("Der Mann","Nomen",0),(",","",7),("der dort steht","Relativsatz",5),(",","",7),("ist mein Onkel","Hauptsatz",2)],"Auf welches Nomen bezieht sich «der»?")],
      "So bestimmst du die Nebensatzart.",["Finde den Nebensatz: Einleitewort und Verb am Ende.","Steht davor ein Nomen, das beschrieben wird? Dann ist es ein Relativsatz.","Fragst du: warum, wann, wenn, obwohl? Dann ist es ein Konjunktionalsatz.","Bestimme bei Konjunktionalsätzen die genaue Art (Grund, Zeit, Bedingung …)."],
      "Das ist wichtig.",[["Relativsatz","Bezieht sich auf ein Nomen.","das Buch, das ich lese",5],["Konjunktionalsatz","Einleitewort verbindet mit dem Hauptsatz.","weil, obwohl, wenn",6],["Komma","Nebensätze trennt man mit Komma.","…, weil …",1]],
      fehler=[["«das ich lese» ist ein Konjunktionalsatz.","«das ich lese» ist ein Relativsatz.","Er beschreibt «Buch»."],["«weil es regnet» ist ein Relativsatz.","«weil es regnet» ist ein Konjunktionalsatz.","Er nennt den Grund."],["Das Buch das ich lese ist neu.","Das Buch, das ich lese, ist neu.","Der Relativsatz steht zwischen Kommas."]])
