def kommaerw(ch,hard):
    t=DT('%s-deu-kommaerw'%ch,ch,'Zeichensetzung','Die erweiterte Kommasetzung',seed=211+int(ch[2:]))
    t.th('basis','Komma bei Nebensätzen','Nebensätze, Relativsätze und Infinitivgruppen mit um, ohne, statt zu trennt man mit Komma ab.')
    THEORY(t,"Du schreibst: «Ich hoffe dass du kommst.» Ein Komma fehlt. Mit der Regel für Nebensätze findest du es sofort.",SC('words',words=[['Ich hoffe','#34A853'],[',','#EA4335'],['dass du kommst','#4285F4']],say='Komma vor dem Nebensatz'),
      "Vier Fälle, in denen ein Komma steht.",["Fall","Regel","Beispiel"],[["{0|Nebensatz}","Komma vor oder nach dem Nebensatz","Ich weiss{0|,} dass du kommst."],["{5|Relativsatz}","Komma davor und danach","Das Buch{5|,} das ich lese{5|,} ist neu."],["{1|um/ohne/statt zu}","Komma vor der Infinitivgruppe","Er geht{1|,} ohne zu grüssen."],["{6|Einschub}","Komma davor und danach","Anna{6|,} meine Freundin{6|,} kommt."]],
      "Die Kommas sind farbig.",
      [([("Ich weiss","Hauptsatz",2),(",","Komma",1),("dass","",6),("du kommst","Nebensatz",0)],"Komma vor dem Nebensatz."),([("Das Buch","",7),(",","Komma",1),("das ich lese","Relativsatz",5),(",","Komma",1),("ist neu","",7)],"Relativsatz: Komma davor und danach."),([("Er geht","",7),(",","Komma",1),("ohne zu grüssen","Infinitivgruppe",3)],"Infinitivgruppe mit «ohne zu».")],
      "So setzt du die Kommas.",["Lies den Satz und suche Verben.","Markiere Nebensätze, Relativsätze und Infinitivgruppen.","Setze ein Komma vor jeden Nebensatz.","Steht der Nebensatz mitten im Satz, setze auch danach ein Komma.","Lies den Satz laut: An Pausen stehen oft Kommas."],
      "Das ist wichtig.",[["Nebensatz","Wird immer abgetrennt.","…, weil …",1],["Relativsatz","Steht zwischen zwei Kommas.","…, das …, …",5],["Infinitivgruppe","Komma bei um, ohne, statt, anstatt zu.","…, um zu …",3]],
      fehler=[["Ich hoffe dass du kommst.","Ich hoffe, dass du kommst.","Komma vor dem Nebensatz."],["Das Buch das ich lese ist neu.","Das Buch, das ich lese, ist neu.","Der Relativsatz hat zwei Kommas."],["Er ging ohne zu grüssen.","Er ging, ohne zu grüssen.","Komma vor «ohne zu»."]])
    if not hard:
        P=[("Ich weiss dass du kommst.","Ich weiss, dass du kommst."),("Wir bleiben zu Hause weil es regnet.","Wir bleiben zu Hause, weil es regnet."),("Das Buch das ich lese ist spannend.","Das Buch, das ich lese, ist spannend."),("Wenn es regnet bleiben wir drinnen.","Wenn es regnet, bleiben wir drinnen."),("Obwohl sie müde war lernte sie weiter.","Obwohl sie müde war, lernte sie weiter."),("Er ging ohne sich zu verabschieden.","Er ging, ohne sich zu verabschieden."),("Sie lernt um die Prüfung zu bestehen.","Sie lernt, um die Prüfung zu bestehen."),("Der Mann der dort steht ist mein Onkel.","Der Mann, der dort steht, ist mein Onkel."),("Ich hoffe dass es dir gut geht.","Ich hoffe, dass es dir gut geht."),("Als ich klein war wohnte ich in Bern.","Als ich klein war, wohnte ich in Bern."),("Sie sagt dass sie müde ist.","Sie sagt, dass sie müde ist."),("Das Kind das lacht heisst Anna.","Das Kind, das lacht, heisst Anna."),("Er blieb im Bett anstatt zur Schule zu gehen.","Er blieb im Bett, anstatt zur Schule zu gehen."),("Ich lerne damit ich bestehe.","Ich lerne, damit ich bestehe.")]
    else:
        P=[("Mein Onkel der in Basel wohnt besucht uns.","Mein Onkel, der in Basel wohnt, besucht uns."),("Anna meine beste Freundin kommt morgen.","Anna, meine beste Freundin, kommt morgen."),("Herr Meier unser Nachbar hat einen Hund.","Herr Meier, unser Nachbar, hat einen Hund."),("Er arbeitet hart um sein Ziel zu erreichen.","Er arbeitet hart, um sein Ziel zu erreichen."),("Sie ging ohne ein Wort zu sagen.","Sie ging, ohne ein Wort zu sagen."),("Er blieb im Bett anstatt zur Schule zu gehen.","Er blieb im Bett, anstatt zur Schule zu gehen."),("Weil es stürmte blieben wir zu Hause.","Weil es stürmte, blieben wir zu Hause."),("Ich glaube dass er kommt weil er es versprochen hat.","Ich glaube, dass er kommt, weil er es versprochen hat."),("Die Frau die uns hilft heisst Anna.","Die Frau, die uns hilft, heisst Anna."),("Wenn du Zeit hast und es dir passt komm vorbei.","Wenn du Zeit hast und es dir passt, komm vorbei."),("Das Haus in dem wir wohnen ist alt.","Das Haus, in dem wir wohnen, ist alt."),("Sie fragte ob der Zug pünktlich ankommt.","Sie fragte, ob der Zug pünktlich ankommt."),("Ich lerne viel damit ich die Prüfung bestehe.","Ich lerne viel, damit ich die Prüfung bestehe."),("Der Lehrer erklärt wie man einen Aufsatz plant.","Der Lehrer erklärt, wie man einen Aufsatz plant.")]
    if hard:more(t,'Einschübe und Infinitivgruppen','Einschübe (Zusätze) stehen zwischen zwei Kommas. Bei um, ohne, statt, anstatt + zu steht ein Komma vor der Infinitivgruppe.',TBL(['Fall','Beispiel'],[['Einschub','Anna{1|,} meine beste Freundin{1|,} kommt morgen.'],['um … zu','Er arbeitet hart{1|,} um sein Ziel zu erreichen.'],['ohne … zu','Sie ging{1|,} ohne ein Wort zu sagen.'],['statt / anstatt … zu','Er blieb im Bett{1|,} anstatt zur Schule zu gehen.']]))
    ex=5
    for i,(pre,a) in enumerate(P):
        w=[pre,pre.replace(' ',', ',1),pre.replace(' ',', ',2)]
        if i<len(P)-ex:
            t.mc(1 if i<6 else 2,"Welcher Satz ist richtig?",a,[x for x in w if x!=a],"Suche den Nebensatz und trenne ihn ab.")
            t.fix(2,"Setze die fehlenden Kommas.",pre,a,"Suche Nebensätze, Relativsätze und Infinitivgruppen.",None)
        else:
            t.emc("Welcher Satz ist richtig?",a,[x for x in w if x!=a],'')
            t.efix("Setze die fehlenden Kommas.",pre,a,'')
    cls(t,[x for pre,a in P for x in ((a,0),(pre,1))],['richtig','falsch'],lambda p:"%s\nSind die Kommas richtig gesetzt?"%p,hint="Nebensätze werden mit Komma abgetrennt.",ne=6,sel=False,ntyp=0,ntx=0,match=False,mt=3,jn=0,mq='Tippe alle Sätze an, die {c} sind.')
    return t
T+= [lambda:kommaerw('kl8',False),lambda:kommaerw('kl9',True)]
